class OAuthPlugin extends MicroPlugin
{
    #[Override]
    public function registerServiceDefinition(array $def): array
    {
        $def[ClientStoreGateway::class] = \DI\autowire(ClientStoreAdapter::class);
        $def[ApiKeyStoreGateway::class] = \DI\autowire(ApiKeyStoreAdapter::class);
        $def[LoginGateway::class] = \DI\autowire(LoginAdapter::class);
        $def[TermsOfUseConsentGateway::class] = \DI\autowire(TermsOfUseConsentAdapter::class);
        $def[RegisterUserGateway::class] = \DI\autowire(RegisterUserAdapter::class);
        $def[ChangePasswordGateway::class] = \DI\autowire(ChangePasswordAdapter::class);
        $def[SessionStoreGateway::class] = \DI\autowire(SessionStoreSqlAdapter::class);
        $def[TemporalKeysGateway::class] = \DI\autowire(TemporalKeysSqlAdapter::class);
        $def[TokenStoreGateway::class] = \DI\autowire(TokenStoreSqlAdapter::class);
        $def[TokenSigner::class] = \DI\autowire(JoseTokenSigner::class);
        $def[UserMfaGateway::class] = \DI\autowire(UserMfaAdapter::class);
        $def[DelegateLoginGateway::class] = \DI\autowire(DelegateLoginAdapter::class);
        $def[ScopesConsentGateway::class] = \DI\autowire(ScopesConsentAdapter::class);
        $def[DeviceAuthorizationGateway::class] = \DI\autowire(DeviceAuthorizationSqlAdapter::class);
        $def[TokenRevocationGateway::class] = \DI\autowire(TokenRevocationSqlAdapter::class);
        $def[ParRequestGateway::class] = \DI\autowire(ParRequestSqlAdapter::class);
        $def[DynamicClientGateway::class] = \DI\autowire(DynamicClientAdapter::class);
        $def[WebAuthnCredentialGateway::class] = \DI\autowire(WebAuthnCredentialSqlAdapter::class);
        $def[WebAuthnChallengeGateway::class] = \DI\autowire(WebAuthnChallengeSqlAdapter::class);
        $def[GdprConsentGateway::class] = \DI\autowire(GdprConsentAdapter::class);
        $def[ProfileGateway::class] = \DI\autowire(ProfileAdapter::class);
        $def[PasswordGateway::class] = \DI\autowire(PasswordAdapter::class);
        $def[MfaGateway::class] = \DI\autowire(MfaAdapter::class);
        $def[SessionsGateway::class] = \DI\autowire(SessionsAdapter::class);
        $def[PasswordRecoveryMailGateway::class] = \DI\autowire(OAuthMailAdapter::class);
        $def[UserRegistrationMailGateway::class] = \DI\autowire(OAuthMailAdapter::class);
        $def[MagicLinkGateway::class] = \DI\autowire(MagicLinkSqlAdapter::class);
        $def[MagicLinkMailGateway::class] = \DI\autowire(MagicLinkMailAdapter::class);
        $def[MagicLinkCodeGateway::class] = \DI\autowire(MagicLinkCodeAdapter::class);
        $def[MagicLinkEnabledGateway::class] = \DI\autowire(MagicLinkEnabledAdapter::class);
        $def[MagicLinkSessionGateway::class] = \DI\autowire(MagicLinkSessionAdapter::class);
        $def[RequestMagicLinkUsecase::class] = \DI\autowire()
            ->constructorParameter('baseUrl', \DI\factory(fn (Context $ctx): string => $ctx->getBaseUrl()));
        $def[UserInvitationQueryGateway::class] = \DI\autowire(UserInvitationQueryAdapter::class);
        $def[UserInvitationMailGateway::class] = \DI\autowire(UserInvitationMailAdapter::class);
        $def[UserInvitationSessionGateway::class] = \DI\autowire(UserInvitationSessionAdapter::class);
        $def[GdprDataExportGateway::class] = \DI\autowire(GdprDataAdapter::class);
        $def[GdprDataDeleteGateway::class] = \DI\autowire(GdprDataAdapter::class);
        return $def;
    }

    #[Override]
    public function registerRoutes(RouteCollectorProxy $collector): void
    {
        $collector->get('/api/me/gdpr/export', [GdprExportController::class, 'export']);
        $collector->delete('/api/me/gdpr/data', [GdprDeleteController::class, 'delete']);
        $collector->get('/api/me/consents', [MeConsentsListController::class, 'list']);
        $collector->get('/api/me/consents/history', [MeConsentsHistoryController::class, 'history']);
        $collector->put('/api/me/consents/{purposeKey}', [MeConsentsGrantController::class, 'grant']);
        $collector->get('/api/me/profile', [ProfileMeController::class, 'get']);
        $collector->put('/api/me/profile', [ProfileMeController::class, 'put']);
        $collector->get('/api/me/sessions', [UserSessionController::class, 'list']);
        $collector->delete('/api/me/sessions', [UserSessionController::class, 'revokeAll']);
        $collector->delete('/api/me/sessions/{sessionId}', [UserSessionController::class, 'revoke']);
        $collector->get('/oauth/openid/-/delegated/verify', [DelegatedController::class, 'verify']);
        $collector->group('/oauth/openid/{tenant}', function (RouteCollectorProxy $group) {
            $group->get('/me', [ProfileHtml::class, 'view']);
            $group->get('/me/edit', [ProfileHtml::class, 'edit']);
            $group->post('/me/edit', [ProfileHtml::class, 'save']);
            $group->get('/me/password', [ProfileHtml::class, 'changePassword']);
            $group->post('/me/password', [ProfileHtml::class, 'savePassword']);
            $group->get('/me/mfa', [ProfileHtml::class, 'mfa']);
            $group->post('/me/mfa', [ProfileHtml::class, 'saveMfa']);
            $group->get('/me/sessions', [ProfileHtml::class, 'sessions']);
            $group->post('/me/sessions/revoke/{sessionId}', [ProfileHtml::class, 'revokeSession']);
            $group->get('/jwks', [JwksController::class, 'get']);
            $group->get('/.well-known/openid-configuration', [OpenIdConfigurationController::class, 'get']);
            $group->post('/token', [TokenController::class, 'post']);
            $group->post('/introspect', [IntrospectionController::class, 'post']);
            $group->post('/par', [ParController::class, 'post']);
            $group->post('/register', [DynamicClientController::class, 'post']);
            $group->get('/register/{client_id}', [DynamicClientController::class, 'get']);
            $group->put('/register/{client_id}', [DynamicClientController::class, 'put']);
            $group->delete('/register/{client_id}', [DynamicClientController::class, 'delete']);
            $group->post('/device', [DeviceAuthorizationController::class, 'post']);
            $group->get('/device/verify', [DeviceVerificationHtml::class, 'verify']);
            $group->post('/device/verify', [DeviceVerificationHtml::class, 'formVerify']);
            $group->post('/api-key/validate', [ApiKeyController::class, 'post']);
            $group->get('/userinfo', [UserInfoController::class, 'get']);

            $group->get('/logout', [LogoutController::class, 'logout']);
            $group->post('/revoke', [LogoutController::class, 'revoke']);

            $group->get('/authorize', [AuthorizeHtml::class, 'authorize']);
            $group->post('/authorize', [AuthorizeHtml::class, 'formAuthorize']);
            $group->get('/check-session', [AuthorizeHtml::class, 'refresh']);
            $group->post('/check-session', [AuthorizeHtml::class, 'refresh']);

            $group->post('/webauthn/register/begin', [WebAuthnController::class, 'registerBegin']);
            $group->post('/webauthn/register/finish', [WebAuthnController::class, 'registerFinish']);
            $group->post('/webauthn/authenticate/begin', [WebAuthnController::class, 'authenticateBegin']);
            $group->post('/webauthn/authenticate/finish', [WebAuthnController::class, 'authenticateFinish']);

            $group->post('/magic-link/request', [MagicLinkRequestController::class, 'request']);
            $group->get('/magic-link/verify', [MagicLinkVerifyHtml::class, 'verify']);

            $group->get('/me/invite', [ProfileHtml::class, 'invite']);
            $group->post('/me/invite', [ProfileHtml::class, 'sendInvite']);

            $group->get('/me/passkeys', [ProfileHtml::class, 'passkeys']);
            $group->post('/me/passkeys/{credentialUid}/delete', [ProfileHtml::class, 'deletePasskey']);
            $group->post('/me/passkeys/{credentialUid}/rename', [ProfileHtml::class, 'renamePasskey']);

            $group->get('/me/consents', [ProfileHtml::class, 'consents']);
            $group->post('/me/consents/revoke/{consentUid}', [ProfileHtml::class, 'revokeConsent']);
            $group->post('/me/consents/revoke/{consentUid}/scope', [ProfileHtml::class, 'revokeConsentScope']);

            $group->get('/me/recovery-codes', [ProfileHtml::class, 'recoveryCodes']);

            $group->get('/me/data-export', [ProfileHtml::class, 'dataExport']);
            $group->post('/me/data-export', [ProfileHtml::class, 'requestDataExport']);

            $group->get('/me/delete-account', [ProfileHtml::class, 'deleteAccount']);
            $group->post('/me/delete-account', [ProfileHtml::class, 'requestDeleteAccount']);

            $group->get('/invitation/accept', [InvitationAcceptHtml::class, 'form']);
            $group->post('/invitation/accept', [InvitationAcceptHtml::class, 'accept']);
        });

        $collector->group('/api/access/invitations', function (RouteCollectorProxy $group) {
            $group->post('', [InvitationCreateController::class, 'create']);
            $group->delete('/{uid}', [InvitationCancelController::class, 'cancel']);
            $group->post('/{uid}/resend', [InvitationResendController::class, 'resend']);
        });
    }
}
